using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, apiKey));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Create the agent with tools
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Description = "An AI research assistant that searches the web and takes notes to produce a summary.",
    Instructions = """
        You are a research agent. When given a topic:
        1. Use the web_search tool to find relevant information (perform multiple searches with different queries).
        2. Use the add_note tool to save key findings as you go.
        3. Use the get_notes tool to review all collected notes.
        4. After gathering enough information, produce a clear, well-structured summary of your findings.
        Be thorough but concise. Cite the sources you found.
        """,
    Tools = [
        AIFunctionFactory.Create(WebSearch, "web_search",
            "Searches the web for a query and returns a list of results with titles, URLs, and snippets."),
        AIFunctionFactory.Create(AddNote, "add_note",
            "Saves a research note with a key finding."),
        AIFunctionFactory.Create(GetNotes, "get_notes",
            "Retrieves all research notes collected so far."),
    ],
};

// Prompt the user for a research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

// --- Tool implementations ---

var notes = new List<string>();

[Description("Searches the web for a query and returns results with titles, URLs, and snippets.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration purposes.
    // Replace with a real search API (Bing, Google, etc.) for production use.
    return $"""
        Search results for: "{query}"

        1. Title: "{query}" - Wikipedia Overview
           URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
           Snippet: A comprehensive overview covering the key aspects, history, and current state of {query}.

        2. Title: Latest Research on {query} - ScienceDaily
           URL: https://www.sciencedaily.com/search/?keyword={Uri.EscapeDataString(query)}
           Snippet: Recent studies and breakthroughs related to {query}, including findings from leading research institutions.

        3. Title: {query}: A Practical Guide - TechReview
           URL: https://www.techreview.com/topic/{Uri.EscapeDataString(query)}
           Snippet: An in-depth practical guide exploring applications, benefits, and challenges of {query}.
        """;
}

string AddNote([Description("The research note to save")] string note)
{
    notes.Add(note);
    return $"Note saved. Total notes: {notes.Count}";
}

string GetNotes()
{
    if (notes.Count == 0)
        return "No notes collected yet.";

    return string.Join("\n", notes.Select((n, i) => $"[{i + 1}] {n}"));
}

