using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(sp =>
    new OpenAIChatClient(new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Note-taking state shared by the tools
var notes = new List<string>();

// Define tools
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearch, "web_search",
        "Searches the web for a query and returns a list of results with titles, URLs, and snippets."),
    AIFunctionFactory.Create(AddNote, "add_note",
        "Saves a research note with a key finding."),
    AIFunctionFactory.Create(GetNotes, "get_notes",
        "Retrieves all research notes collected so far."),
};

// Create the agent
